<?php $title='Page & Security Monitoring';$h=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$summary=$report['summary'];ob_start(); ?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h3 class="mb-1">Page &amp; Security Monitoring</h3><p class="text-muted mb-0">Understand page traffic, response times, and security activity.</p></div><a class="btn btn-outline-primary" href="<?= url('?route=admin/monitoring&from='.rawurlencode($from).'&to='.rawurlencode($to)) ?>">Refresh</a></div>
<form class="card p-3 mb-3" method="get"><input type="hidden" name="route" value="admin/monitoring"><div class="d-flex flex-wrap gap-3 align-items-end"><label>From<input type="date" class="form-control" name="from" required value="<?= $h($from) ?>"></label><label>To<input type="date" class="form-control" name="to" required value="<?= $h($to) ?>"></label><button class="btn btn-primary">Apply dates</button><a class="btn btn-outline-secondary" href="<?= url('?route=admin/monitoring') ?>">Reset to last 7 days</a></div></form>
<div class="row g-3 mb-3"><?php foreach(['Page views'=>number_format($summary['views']),'Visitor sessions'=>number_format($summary['visitors']),'Average server response'=>number_format($summary['average_ms'] ?? 0).' ms','Page server errors'=>number_format($summary['errors'] ?? 0)] as $label=>$value): ?><div class="col-6 col-xl-3"><div class="card p-3 h-100"><span class="text-muted small"><?= $h($label) ?></span><h3 class="mb-0 mt-2"><?= $h($value) ?></h3></div></div><?php endforeach; ?></div>
<div class="alert alert-primary">Live records start after installation. Visitor sessions are anonymous browser sessions, not unique people. Response time measures server processing, not the full browser load. Redirects, background requests, and form submissions are excluded from page views.</div>
<div class="card p-3 mb-3"><h5>Daily page views</h5><div class="d-flex gap-2 align-items-end" style="min-height:120px;overflow-x:auto"><?php $max=max(array_merge([1],array_column($report['daily'],'views')));foreach($report['daily'] as $day): ?><div class="text-center flex-fill" style="min-width:65px"><small><?= (int)$day['views'] ?></small><div class="bg-primary rounded-top mx-auto" style="width:75%;height:<?= max(3,(int)round($day['views']/$max*90)) ?>px" aria-label="<?= $h($day['day']) ?>: <?= (int)$day['views'] ?> views"></div><small class="text-muted"><?= $h(substr($day['day'],5)) ?></small></div><?php endforeach; ?><?php if(!$report['daily']): ?><p class="text-muted">No page views for these dates.</p><?php endif; ?></div></div>
<div class="card p-3 mb-3"><h5>Pages visited <small class="text-muted">(top 100)</small></h5><div class="table-responsive"><table id="monitor-pages" class="table table-hover align-middle"><thead><tr><th>Page</th><th>Views</th><th>Average response</th><th>Failed requests</th></tr></thead><tbody><?php foreach($report['pages'] as $page): ?><tr><td><?= $h($page['route']) ?></td><td><?= (int)$page['views'] ?></td><td><?= (int)$page['average_ms'] ?> ms</td><td><?= (int)$page['errors'] ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card p-3"><h5>Security activity</h5><p class="text-muted small">These are recorded events for review; a failed request alone does not prove an attack. Staff see only records for their assigned branch. Admin and Superadmin can see all branches.</p><div class="d-flex flex-wrap gap-2 mb-3"><?php foreach($report['counts'] as $c): ?><span class="badge bg-light text-dark border"><?= $h(ucwords(str_replace('_',' ',$c['event_type']))) ?>: <?= (int)$c['total'] ?></span><?php endforeach; ?></div><p class="text-muted small">Latest 200 events within the selected dates.</p><div class="table-responsive"><table id="monitor-security" class="table table-hover align-middle"><thead><tr><th>Time</th><th>Event</th><th>Page</th><th>User ID</th><th>Branch ID</th><th>Response code</th></tr></thead><tbody><?php foreach($report['events'] as $event): ?><tr><td class="text-nowrap"><?= $h($event['created_at']) ?></td><td><?= $h(ucwords(str_replace('_',' ',$event['event_type']))) ?></td><td><?= $h($event['route']) ?></td><td><?= $h($event['user_id'] ?? 'Guest') ?></td><td><?= $h($event['branch_id'] ?? 'Public / unassigned') ?></td><td><?= (int)$event['status_code'] ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){if(window.jQuery&&jQuery.fn.DataTable){jQuery('#monitor-pages').DataTable({pageLength:10,order:[]});jQuery('#monitor-security').DataTable({pageLength:10,order:[]});}});</script>
<?php $content=ob_get_clean();require __DIR__.'/../layouts/admin.php'; ?>
